pub fn legacy_song_tween_messages(lua: &mlua::Lua) -> Vec<crate::SongLuaStatefulMessageCapture> {
    let mut captures = crate::lua_util::stateful_message_captures(lua);
    for capture in &mut captures {
        capture
            .writes
            .retain(|write| crate::tween_pose::TARGETS.contains(&write.target));
        for (_, targets) in &mut capture.overlay_targets {
            targets.retain(|target| crate::tween_pose::TARGETS.contains(target));
        }
        capture
            .overlay_targets
            .retain(|(_, targets)| !targets.is_empty());
    }
    captures.retain(|capture| !capture.writes.is_empty());
    captures
}

