    let targets: Vec<_> = super::actors::IMMEDIATE_CAPTURE_TARGETS
        .iter()
        .chain(super::actors::SCHEDULED_RENDER_TARGETS)
        .copied()
        .collect();
    legacy_drain_song_property_subset(lua, &targets)
}

fn legacy_drain_song_property_subset(
    lua: &mlua::Lua,
    targets: &[crate::SongLuaOverlayUpdateTarget],
) -> Result<Vec<super::SongReplayPropertyUpdates>, String> {
    let mut output = Vec::new();
    crate::lua_util::drain_overlay_update_capture(
        lua,
        |index, values, scheduled, finals, reset| {
            let values = values
                .iter()
                .filter(|(target, _)| targets.contains(target))
                .cloned()
                .collect::<Vec<_>>();
            let final_values = finals
                .iter()
                .filter(|(target, _)| targets.contains(target))
                .cloned()
                .collect::<Vec<_>>();
            let scheduled = scheduled
                .iter()
                .filter(|update| targets.contains(&update.target))
                .map(|update| super::SongReplayScheduledUpdate {
                    progress: update.progress.clone(),
                    dispatch_seconds: update.dispatch_seconds,
                    frame_advance: update.frame_advance,
                    initial_value: update.initial_value.clone(),
                    delay_seconds: update.delay_seconds,
                    duration_seconds: update.duration_seconds,
                    easing: update.easing.clone(),
                    opt1: update.opt1,
                    target: update.target,
                    value: update.value.clone(),
                })
                .collect::<Vec<_>>();
            if !values.is_empty() || !scheduled.is_empty() || !final_values.is_empty() || reset {
                output.push(super::SongReplayImmediateUpdates {
                    overlay_index: index,
                    values,
                    scheduled,
                    final_values,
                    tween_reset: reset,
                });
            }
            Ok(())
        },
    )?;
    Ok(output)
}

pub fn legacy_drain_song_overlay_updates(
    lua: &mlua::Lua,
) -> Result<Vec<super::SongReplayPropertyUpdates>, String> {
    let targets: Vec<_> = super::actors::IMMEDIATE_CAPTURE_TARGETS
        .iter()
        .chain(super::actors::SCHEDULED_RENDER_TARGETS)
        .chain(crate::tween_pose::TARGETS.iter())
        .chain(super::actors::MEDIA_CAPTURE_TARGETS)
        .copied()
        .collect();
    legacy_drain_song_property_subset(lua, &targets)
}

