#[test]
fn startup_queue_collection_preserves_enqueue_order_and_includes_zero_update() {
    let dir = tempfile::tempdir().unwrap();
    let path = write(
        dir.path(),
        "default.lua",
        r#"
        return Def.ActorFrame{
            Name='parent',
            OnCommand=function(self)self:queuecommand('Later')end,
            LaterCommand=function()log('future-parent')end,
            Def.ActorFrame{
                Name='child',
                OnCommand=function(self)self:queuecommand('Later')end,
                LaterCommand=function()log('future-child')end,
            },
            Def.ActorFrame{
                Name='update',
                InitCommand=function(self)
                    self:SetUpdateFunction(function(self)self:queuecommand('Later')end)
                end,
                LaterCommand=function()log('future-update')end,
            },
        }
    "#,
    );
    let context = SongLuaCompileContext::new(dir.path(), "queue collection");
    let mut pair = Pair::new(context);
    let (native, _) = pair.activate(&[&path]);
    let names = native
        .startup_queue
        .iter()
        .map(|t| t.get::<String>("Name").unwrap())
        .collect::<Vec<_>>();
    assert!(names.ends_with(&["parent".into(), "child".into(), "update".into()]));
    let queue = test_support::song_startup_queue(&pair.rust);
    let actual = queue
        .into_iter()
        .map(|t| {
            let Value::Table(t) = t else { panic!() };
            let key = pair.rust.vm_mut().try_intern(b"Name").unwrap();
            let Value::String(n) = pair.rust.vm_mut().raw_table_get(t, key).unwrap() else {
                panic!()
            };
            String::from_utf8_lossy(pair.rust.vm_mut().string_bytes(n).unwrap()).into_owned()
        })
        .collect::<Vec<_>>();
    if actual != names {
        for actor in &native.startup_queue {
            let description:String=pair.native.load("local a=...;return table.concat({tostring(a.Name),tostring(a.__songlua_actor_type),tostring(a.__songlua_script_dir),tostring(a.__songlua_top_screen_child_name),tostring(a._Source),tostring(a._Line)},' / ')").call(actor).unwrap();
            eprintln!("native pending: {description}");
        }
        for actor in test_support::song_startup_queue(&pair.rust) {
            pair.rust
                .vm_mut()
                .set_global(b"probe_pending", actor)
                .unwrap();
            let value=pair.rust.vm_mut().execute(&compile_named(b"local a=probe_pending;return table.concat({tostring(a.Name),tostring(a.__songlua_actor_type),tostring(a.__songlua_script_dir),tostring(a.__songlua_top_screen_child_name),tostring(a._Source),tostring(a._Line)},' / ')",b"=pending probe").unwrap()).unwrap()[0];
            let Value::String(value) = value else {
                panic!()
            };
            eprintln!(
                "rust pending: {}",
                String::from_utf8_lossy(pair.rust.vm_mut().string_bytes(value).unwrap())
            );
        }
    }
    assert_eq!(actual, names);
    assert_eq!(pair.compare(), "");
}

