    let (_, activation) = pair.activate(&[&path]);
    let mut foreign = RustSongRuntime::new(&pair.context).unwrap();
    assert!(
        !foreign
            .discover_song_startup_commands(pair.scene, &activation)
            .unwrap()
    );
    assert!(!foreign.restore_song_startup_locals(pair.scene).unwrap());
    pair.rust
        .discover_song_startup_commands(pair.scene, &activation)
