    for (seconds, delta) in [
        (0.125, 0.125),
        (0.5, 0.375),
        (1., 0.5),
        (1.5, 0.5),
        (2., 0.5),
    ] {
        pair.rust
            .set_values((seconds * 2.) as f32, seconds as f32)
            .unwrap();
        test_support::legacy_advance_song_replay(&pair.native, &native, seconds, delta).unwrap();
