        "saved.sprite:setstate(-1):setstate(1.5):setstate({});assert(not pcall(function()saved.sprite:cullmode('invalid')end));assert(not pcall(function()saved.aft:EnablePreserveTexture(1)end))",
        "saved.aft:Create()",
