fn install_capture_timeline(pair: &Pair, deltas: &[f64]) {
    let frames: Vec<_> = deltas
        .iter()
        .enumerate()
        .map(|(i, &dt)| (i as f64, dt))
        .collect();
    test_support::legacy_set_song_replay_frames(&pair.native, &frames).unwrap();
}

fn advance_capture_frame(
    pair: &mut Pair,
    native: &test_support::LegacySongActivation,
    index: usize,
    seconds: f64,
    delta: f64,
) {
    pair.rust.set_values(index as f32, seconds as f32).unwrap();
    deadsync_song_lua::set_compile_song_runtime_values(&pair.native, index as f32, seconds as f32)
        .unwrap();
    test_support::legacy_advance_song_replay_at_frame(&pair.native, native, index, delta).unwrap();
    pair.rust
        .advance_song_replay(pair.scene, seconds, delta)
        .unwrap();
    pair.compare();
    compare_immediate_updates(pair);
}

