            .discover_song_startup_commands(pair.scene, &rust)
            .unwrap()
    );
    let actual = pair.rust.song_startup_queued_states(pair.scene).unwrap();
    for key in ["text", "sprite"] {
        let (a, b) = saved_pair(&mut pair, key);
        let a = a.to_pointer() as usize;
        assert_eq!(
            rust.updates.get(&b),
            native.updates.get(&a),
            "initial update {key}"
        );
        assert_eq!(rust.tweens.get(&b), native.tweens.get(&a), "startup {key}");
        assert_eq!(actual.get(&b), expected.get(&a), "queued {key}");
        assert!(actual.contains_key(&b), "queued capture missing {key}");
    }
    pair.compare();
}

